import { assetManager, sys } from 'cc';
import type { BundleVersionInfo } from './BundleVersionInfo';
import { HOT_UPDATE_ENABLED_BUNDLES } from './HotUpdateConfig';
import type { HotUpdateView } from './HotUpdateView';

// 大廳透過 globalThis.__subGameData__ 傳進來的資料
interface SubGameData {
    cdnBase: string;
    gameId: string;
}

// 純函式版本檢查 不依賴 Component/Inspector
// GameRoot.initial() 在 LoadingView 之前呼叫
export async function checkWebBundleVersion(bundleName: string, ui?: HotUpdateView): Promise<void> {
    if (sys.isNative) {
        console.info(`[WebBundleVersionCheck] 原生平台由 NativeBundleUpdater 處理 略過 Web 版本檢查`);
        return;
    }
    if (!HOT_UPDATE_ENABLED_BUNDLES.has(bundleName)) {
        console.info(`[WebBundleVersionCheck] ${bundleName} 不在熱更白名單內 略過`);
        return;
    }

    // __subGameData__ 存在代表從大廳載入 沒有就是 slot_game 獨立 Editor Preview
    const subGameData = (globalThis as any).__subGameData__ as SubGameData | undefined;
    console.info(`[WebBundleVersionCheck] 收到大廳資料 __subGameData__=`, JSON.stringify(subGameData ?? null));
    if (!subGameData?.cdnBase) {
        console.info(`[WebBundleVersionCheck] 沒有大廳傳入的 cdnBase 略過版本檢查`);
        return;
    }

    const cdnBase = subGameData.cdnBase.replace(/\/+$/, '');
    const versionUrl = `${cdnBase}/remote/${bundleName}/version.json`;

    ui?.show();
    ui?.setStatus('檢查版本中...');
    ui?.setProgress(0.1);
    console.info(`[WebBundleVersionCheck] 開始檢查 bundle=${bundleName} cdnBase=${cdnBase}`);
    console.info(`[WebBundleVersionCheck] 查詢 ${versionUrl}`);

    try {
        const res = await fetch(`${versionUrl}?t=${Date.now()}`);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const remote = (await res.json()) as BundleVersionInfo;
        ui?.setProgress(0.5);

        console.info(`[WebBundleVersionCheck] 遠端回應 bundleName=${remote.bundleName} version=${remote.version} packageUrl=${remote.packageUrl}`);

        if (remote.bundleName !== bundleName) {
            console.warn(`[WebBundleVersionCheck] bundleName 不符 遠端=${remote.bundleName} 預期=${bundleName} 略過`);
            ui?.setStatus('版本資訊異常 使用保底版本');
            ui?.setProgress(1);
            return;
        }

        const cached = assetManager.getBundle(bundleName);
        if (!cached) {
            console.info(`[WebBundleVersionCheck] bundle 尚未載入 無法比對`);
            ui?.setStatus('檢查完成');
            ui?.setProgress(1);
            return;
        }

        const cachedBase = ((cached as any).base || '').replace(/\/+$/, '');
        const remoteBase = remote.packageUrl.replace(/\/+$/, '');
        ui?.setProgress(0.8);

        if (cachedBase === remoteBase) {
            console.info(`[WebBundleVersionCheck] 版本一致 v${remote.version} 不需更新`);
            ui?.setStatus(`版本 v${remote.version} 已是最新`);
            ui?.setProgress(1);
        } else {
            console.warn(`[WebBundleVersionCheck] 偵測到新版本`);
            console.warn(`[WebBundleVersionCheck]   目前載入: ${cachedBase}`);
            console.warn(`[WebBundleVersionCheck]   遠端最新: v${remote.version} ${remoteBase}`);
            console.warn(`[WebBundleVersionCheck]   Web 平台需要重新整理頁面才能套用新版本`);
            ui?.setStatus(`發現新版本 v${remote.version} 請重新整理頁面`);
            ui?.setProgress(1);
        }
    } catch (err) {
        console.warn(`[WebBundleVersionCheck] 版本檢查失敗 使用保底版本繼續`, err);
        ui?.setStatus('版本檢查失敗 使用保底版本');
        ui?.setProgress(1);
    }
}
