import type { SlotGrid } from './SlotGrid';

/** 中獎位置 已對齊 SlotGrid 的 canonical row（buffer 已移除，跟 grid.columns[].symbolIds 同一套座標） */
export interface SlotAwardPosition {
    readonly col: number;
    readonly row: number;
}

export interface SlotAward {
    readonly symbolId: number;
    readonly count: number;
    readonly positions: readonly SlotAwardPosition[];
    readonly pay: string;
}

export interface SlotRoundStep {
    readonly grid: SlotGrid;
    readonly awards: readonly SlotAward[];
    readonly win: string;
}

export interface SlotFreeMultiplierStep {
    readonly round: number;
    readonly multiplier: number;
    readonly accumulated: number;
    readonly win: string;
}

/** 中性的 JP 等級名稱 */
export type SlotJackpotTier = 'mini' | 'minor' | 'major' | 'grand';

export interface SlotJackpotResult {
    readonly won: boolean;
    readonly tier: SlotJackpotTier | '';
    readonly payout: string;
    readonly currency: string;
}

/** Main／Free 局的 Grid／Awards 解碼結果，跟「這是哪次 spin」無關，History Detail 沒有 spin 信封欄位時也能重用 */
export interface SlotRoundSteps {
    readonly mainSteps: readonly SlotRoundStep[];
    readonly freeRounds: readonly (readonly SlotRoundStep[])[];
    readonly freeSpinTriggered: boolean;
    readonly freeMultipliers: readonly SlotFreeMultiplierStep[];
    /** 這一局的整體倍率 */
    readonly multiplier: number;
}

/** Spin 一局的正規化結果 後端格式無關 Handler／Task／Controller／Presentation 只認這個型別 */
export interface SlotRoundResult extends SlotRoundSteps {
    readonly operationId: string;
    readonly betId?: string;
    readonly totalWin: string;
    readonly rawEngineWin: string;
    readonly engineWin: string;
    readonly maxWin: {
        readonly applied: boolean;
        readonly multiplier: string;
        readonly capAmount: string;
    };
    readonly balanceAfter: string;
    readonly outcome: 'won' | 'lost';
    readonly freeRound: boolean;
    readonly chargedWager: string;
    readonly jackpot: SlotJackpotResult;
}
